// SPDX-License-Identifier: Apache-2.0
//! The moment aggregates as whole-partition window aggregates against Spark
//! 4.2: `tests/fixtures/spark-4.2.0/moment-window-goldens.json` (generated by
//! `tests/scripts/gen_moment_window_goldens.py` from a real Spark run) holds
//! `fn(..) OVER (PARTITION BY g)` over a table of NULLs, NaN, infinities,
//! `-0.0`, huge values and one-row, all-NULL and constant groups. A case must
//! give Spark's values bit for bit (two NaNs match) or Spark's error class.
//! Cases the engine refuses are listed in `REFUSED` and must keep failing with
//! `KRISHIV_UNSUPPORTED_FEATURE`, so enabling one forces the list to shrink.
#![cfg(test)]

use std::path::Path;

use arrow_array::cast::AsArray;
use arrow_array::types::{Float64Type, Int32Type, Int64Type};
use arrow_array::{Array, ArrayRef};
use arrow_schema::DataType;
use futures::executor::block_on;
use krishiv_session::Session;
use serde_json::Value;

/// Window forms the engine does not run yet (function names).
const REFUSED: [&str; 0] = [];

fn cell(a: &ArrayRef, i: usize) -> String {
    if a.is_null(i) {
        return "None".to_owned();
    }
    match a.data_type() {
        DataType::Int32 => a.as_primitive::<Int32Type>().value(i).to_string(),
        DataType::Int64 => a.as_primitive::<Int64Type>().value(i).to_string(),
        DataType::Float64 => format!("{:?}", a.as_primitive::<Float64Type>().value(i)),
        t => format!("unexpected {t}"),
    }
}

/// Two renderings of one value: equal text, or equal doubles bit for bit
/// (NaN equals NaN).
fn same(got: &str, want: &str) -> bool {
    if got == want {
        return true;
    }
    match (got.parse::<f64>(), want.parse::<f64>()) {
        (Ok(g), Ok(w)) => (g.is_nan() && w.is_nan()) || g.to_bits() == w.to_bits(),
        _ => false,
    }
}

#[test]
fn moment_window_aggregates_match_spark() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/spark-4.2.0/moment-window-goldens.json");
    let doc: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let s = Session::new().unwrap();
    block_on(async {
        s.sql(doc["view"].as_str().unwrap())
            .await
            .unwrap()
            .collect()
            .await
            .unwrap();
    });
    let mut wrong = Vec::new();
    let mut refused = Vec::new();
    for case in doc["cases"].as_array().unwrap() {
        let sql = case["sql"].as_str().unwrap();
        let name = sql.split(['(', ' ']).nth(3).unwrap_or("?").to_owned();
        let result = block_on(async { s.sql(sql).await?.collect().await });
        match (result, case.get("rows")) {
            (Ok(batches), Some(want)) => {
                let mut got = Vec::new();
                for b in &batches {
                    for i in 0..b.num_rows() {
                        got.push((cell(b.column(0), i), cell(b.column(1), i)));
                    }
                }
                let want: Vec<(String, String)> = want
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|r| {
                        (
                            r[0].as_str().unwrap().to_owned(),
                            r[1].as_str().unwrap().to_owned(),
                        )
                    })
                    .collect();
                let ok = got.len() == want.len()
                    && got
                        .iter()
                        .zip(&want)
                        .all(|(g, w)| g.0 == w.0 && same(&g.1, &w.1));
                if !ok {
                    wrong.push(format!("{sql}\n  got  {got:?}\n  want {want:?}"));
                }
            }
            (Err(e), Some(_)) if e.error_class().name() == "KRISHIV_UNSUPPORTED_FEATURE" => {
                refused.push(name);
            }
            (Err(e), Some(_)) => wrong.push(format!("{sql}: {}", e.error_class().name())),
            (Err(e), None) => {
                // Spark raised; the engine must raise something of the same family.
                let want = case["error"].as_str().unwrap();
                if !want.contains(e.error_class().name().split('.').next().unwrap_or("")) {
                    wrong.push(format!(
                        "{sql}: engine {}, Spark {want}",
                        e.error_class().name()
                    ));
                }
            }
            (Ok(_), None) => wrong.push(format!("{sql}: Spark raised, the engine did not")),
        }
    }
    assert!(
        wrong.is_empty(),
        "{} differ:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
    assert_eq!(refused, REFUSED, "refused window forms");
}
